'use strict';

// MAIN //

/**
* Handles message of type `execute_request`.
*
* @private
* @param {Message} request - `kernel_info_request`
* @returns {Message} `kernel_info_reply`
*/
function executeReply( request ) {
	// FIXME: there's a lot to check in request's contents
	var code;

	return request.content.code;

	repl.emit( 'input', code );

	repl.on( 'command', onCommand );

	/**
	* Callback invoked upon executing a command.
	*
	* @private
	* @param {string} cmd - command
	* @param {boolean} success - boolean indicating whether the command successfully executed
	* @param {*} res - result
	*/
	function onCommand( cmd, success, res ) {
		// FIXME: this file is a disaster
		return {
			'execute_reply': request.createReply( 'execute_reply', {
				'status': 'ok',
				'execution_count': self._count,
				'payload': [],
				'user_expressions': {}
			}),
			'execute_result': request.createReply( 'execute_result', {
				'execution_count': self._count,
				'data': {
					'text/plain': res
				},
				'metadata': {}
			}),
		}
	}
}


// EXPORTS //

module.exports = executeReply;
